/**
 * Durable asset store — the provider-agnostic bridge between the AI image lab and `lib/storage`.
 *
 * No storage vendor is approved yet (STORAGE_DECISION.md), so this suite proves two things at
 * once: (1) with a durable provider supplied, generated bytes are stored under the *owning
 * tenant's* key prefix and only a durable URL + provenance reaches the database; (2) with no
 * durable provider configured — today's state — resolution returns nothing and the image lab
 * keeps failing closed with its honest 503 before any work happens. Nothing here enables a
 * provider or fakes a generation.
 */

import { describe, expect, it, vi } from "vitest";

vi.mock("@/lib/db", () => ({ default: { mediaAsset: { create: vi.fn(async () => ({ id: "unused" })) } } }));

import { createImageAssetStore, resolveImageAssetStore, type CreateMediaAsset } from "@/lib/ai/assetStore";
import { enhanceStudioImage, generateStudioImages } from "@/lib/ai/imageLab";
import { hasDurableStorage, resolveDurableStorageProvider, type ObjectStorageProvider, type PutObjectInput } from "@/lib/storage";
import { dataUrlFor, jpegBytes, textBytes } from "../helpers/imageFixtures";

const BUSINESS = "business-a";
const OTHER_BUSINESS = "business-b";

class FakeDurableProvider implements ObjectStorageProvider {
  readonly id = "fake-durable";
  readonly capabilities = { durable: true, cdn: true, maxObjectBytes: 12 * 1024 * 1024, derivatives: true, models: false };
  puts: PutObjectInput[] = [];
  removed: string[] = [];
  keyFor = (input: PutObjectInput) => `tenants/${input.businessId}/${input.kind}/${input.name}`;
  urlFor = (key: string) => `https://cdn.example.test/${key}`;

  async put(input: PutObjectInput) {
    this.puts.push(input);
    const key = this.keyFor(input);
    return { provider: this.id, key, url: this.urlFor(key), bytes: input.body.length, contentType: input.contentType };
  }

  async remove(ref: { key: string }) {
    this.removed.push(ref.key);
  }
}

function generatedJpeg() {
  return {
    dataUrl: dataUrlFor(jpegBytes({ width: 800, height: 600 }), "image/jpeg"),
    mime: "image/jpeg",
    width: 800,
    height: 600,
    representative: false,
  };
}

describe("createImageAssetStore", () => {
  it("stores bytes under the owning tenant's prefix and records only a durable URL + provenance", async () => {
    const provider = new FakeDurableProvider();
    const rows: Parameters<CreateMediaAsset>[0][] = [];
    const store = createImageAssetStore(provider, async (data) => {
      rows.push(data);
      return { id: "asset-1" };
    });

    const asset = await store({
      businessId: BUSINESS,
      image: generatedJpeg(),
      alt: "Nyama choma platter",
      source: "AI_GENERATED",
      label: "AI_GENERATED",
      generationId: "gen-123",
      parentAssetId: "asset-0",
    });

    expect(asset?.id).toBe("asset-1");
    expect(asset?.url).toMatch(/^https:\/\/cdn\.example\.test\/tenants\/business-a\/image-original\//);
    expect(provider.puts).toHaveLength(1);
    expect(provider.puts[0].businessId).toBe(BUSINESS);
    expect(provider.puts[0].kind).toBe("image-original");
    expect(provider.puts[0].name).toMatch(/^ai-[0-9a-f-]+\.jpg$/);
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({
      businessId: BUSINESS,
      kind: "IMAGE",
      source: "AI_GENERATED",
      label: "AI_GENERATED",
      aiGenerationId: "gen-123",
      parentAssetId: "asset-0",
      mime: "image/jpeg",
      width: 800,
      height: 600,
    });
    // The database row must never carry image bytes.
    expect(JSON.stringify(rows[0])).not.toContain("data:image");
  });

  it("refuses a provider that answers with another tenant's key, and cleans up", async () => {
    const provider = new FakeDurableProvider();
    provider.keyFor = (input) => `tenants/${OTHER_BUSINESS}/${input.kind}/${input.name}`;
    const create = vi.fn(async () => ({ id: "asset-x" }));
    const store = createImageAssetStore(provider, create);

    const asset = await store({
      businessId: BUSINESS,
      image: generatedJpeg(),
      alt: null,
      source: "AI_GENERATED",
      label: "AI_GENERATED",
      generationId: null,
    });

    expect(asset).toBeNull();
    expect(create).not.toHaveBeenCalled();
    expect(provider.removed).toHaveLength(1);
    expect(provider.removed[0]).toContain(OTHER_BUSINESS);
  });

  it("refuses inline data URLs from a mis-declared provider", async () => {
    const provider = new FakeDurableProvider();
    provider.urlFor = () => dataUrlFor(jpegBytes(), "image/jpeg");
    const store = createImageAssetStore(provider, async () => ({ id: "asset-x" }));

    const asset = await store({
      businessId: BUSINESS,
      image: generatedJpeg(),
      alt: null,
      source: "AI_GENERATED",
      label: "AI_GENERATED",
      generationId: null,
    });

    expect(asset).toBeNull();
    expect(provider.removed).toHaveLength(1);
  });

  it("removes the stored object when the metadata write fails (no orphans)", async () => {
    const provider = new FakeDurableProvider();
    const store = createImageAssetStore(provider, async () => {
      throw new Error("db unavailable");
    });

    const asset = await store({
      businessId: BUSINESS,
      image: generatedJpeg(),
      alt: null,
      source: "ENHANCED",
      label: "ACTUAL",
      generationId: "gen-9",
    });

    expect(asset).toBeNull();
    expect(provider.removed).toHaveLength(1);
  });

  it("never sends invalid bytes to the provider", async () => {
    const provider = new FakeDurableProvider();
    const store = createImageAssetStore(provider, async () => ({ id: "asset-x" }));

    const asset = await store({
      businessId: BUSINESS,
      image: { dataUrl: dataUrlFor(textBytes(), "image/jpeg"), mime: "image/jpeg", width: 10, height: 10, representative: false },
      alt: null,
      source: "AI_GENERATED",
      label: "AI_GENERATED",
      generationId: null,
    });

    expect(asset).toBeNull();
    expect(provider.puts).toHaveLength(0);
  });

  it("does nothing for a non-durable provider", async () => {
    const provider = new FakeDurableProvider();
    (provider as { capabilities: object }).capabilities = { ...provider.capabilities, durable: false };
    const store = createImageAssetStore(provider, async () => ({ id: "asset-x" }));

    const asset = await store({
      businessId: BUSINESS,
      image: generatedJpeg(),
      alt: null,
      source: "AI_GENERATED",
      label: "AI_GENERATED",
      generationId: null,
    });

    expect(asset).toBeNull();
    expect(provider.puts).toHaveLength(0);
  });
});

describe("durable storage resolution (today: nothing approved)", () => {
  it("returns no store and no durable provider by default or for an unimplemented selection", () => {
    expect(resolveDurableStorageProvider({} as NodeJS.ProcessEnv)).toBeNull();
    expect(hasDurableStorage({} as NodeJS.ProcessEnv)).toBe(false);
    expect(resolveImageAssetStore({} as NodeJS.ProcessEnv)).toBeUndefined();
    // Selecting an evaluated-but-unapproved provider must not throw or silently enable writes.
    const env = { JATA_STORAGE_PROVIDER: "vercel-blob" } as unknown as NodeJS.ProcessEnv;
    expect(resolveDurableStorageProvider(env)).toBeNull();
    expect(hasDurableStorage(env)).toBe(false);
    expect(resolveImageAssetStore(env)).toBeUndefined();
  });

  it("the image lab still fails closed with 503 when no store is supplied", async () => {
    const generated = await generateStudioImages({ businessId: BUSINESS, preset: "product-photo" });
    expect(generated.status).toBe("error");
    if (generated.status === "error") {
      expect(generated.httpStatus).toBe(503);
      expect(generated.code).toBe("inline_media_persistence_disabled");
    }

    const enhanced = await enhanceStudioImage({
      businessId: BUSINESS,
      imageDataUrl: dataUrlFor(jpegBytes(), "image/jpeg"),
      mode: "device",
    });
    expect(enhanced.status).toBe("error");
    if (enhanced.status === "error") {
      expect(enhanced.httpStatus).toBe(503);
      expect(enhanced.code).toBe("inline_media_persistence_disabled");
    }
  });
});
